function snapPoint(point,start=null,shift=false){let p={...point},type='FREE';const threshold=12/Math.max(.005,App.camera.scale);let candidates=[];if(App.endpoints){for(const e of App.doc.elements){if(!['wall','beam','line'].includes(e.type))continue;for(const q of [{x:e.x1,y:e.y1},{x:e.x2,y:e.y2}])candidates.push({...q,kind:'ENDPOINT',priority:0});if($('snapMidpoint')?.checked)candidates.push({x:(e.x1+e.x2)/2,y:(e.y1+e.y2)/2,kind:'MIDPOINT',priority:1})}}if($('snapIntersection')?.checked){const lines=App.doc.elements.filter(e=>['wall','beam','line'].includes(e.type));for(let i=0;i<lines.length&&i<120;i++)for(let j=i+1;j<lines.length&&j<120;j++){const q=intersectLines(lines[i],lines[j]);if(q&&q.t>=0&&q.t<=1&&q.u>=0&&q.u<=1)candidates.push({x:q.x,y:q.y,kind:'INTERSECTION',priority:0})}}candidates=candidates.filter(q=>Math.hypot(q.x-p.x,q.y-p.y)<=threshold).sort((a,b)=>a.priority-b.priority||Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));if(candidates.length){p={x:candidates[0].x,y:candidates[0].y};type=candidates[0].kind}else if(App.snap){const g=getConfig().grid;p.x=Math.round(p.x/g)*g;p.y=Math.round(p.y/g)*g;type='GRID'}if(start&&App.ortho&&!shift&&App.tool==='wall'){const dx=p.x-start.x,dy=p.y-start.y;if(Math.abs(dx)>=Math.abs(dy))p.y=start.y;else p.x=start.x;type+=' / ORTHO'}return {...p,snap:type}}
