function projectOnHost(p){let best=null;for(const e of App.doc.elements.filter(x=>x.type==='wall'&&x.visible!==false)){const dx=e.x2-e.x1,dy=e.y2-e.y1,length=Math.hypot(dx,dy);if(length<500)continue;let u=Math.max(0,Math.min(1,((p.x-e.x1)*dx+(p.y-e.y1)*dy)/(length*length)));const q={x:e.x1+u*dx,y:e.y1+u*dy},distance=Math.hypot(p.x-q.x,p.y-q.y);if(!best||distance<best.distance)best={wall:e,u,q,distance,length}}return best}
