function projection(x,y,z=0){const c=App.camera,{w,h}=rectangles(),s=c.scale;let u=x,v=y;if(App.view==='iso'){let cy=Math.cos(c.yaw),sy=Math.sin(c.yaw),cp=Math.cos(c.pitch),sp=Math.sin(c.pitch);u=x*cy-y*sy;v=(x*sy+y*cy)*sp-z*cp}else if(App.view==='front'){u=x;v=-z}else if(App.view==='rear'){u=-x;v=-z}else if(App.view==='right'){u=y;v=-z}else if(App.view==='left'){u=-y;v=-z}else v=-y;return {x:w/2+c.ox+u*s,y:h/2+c.oy+v*s}}
