function allProjectionCoords(){let points=[];for(const e of App.doc.elements){if(!e.visible)continue;let base=['door','window'].includes(e.type)?element(e.hostId):e;if(!base||base.x1==null)continue;for(const [x,y] of [[base.x1,base.y1],[base.x2,base.y2]]){points.push([x,y,base.z||0],[x,y,(base.z||0)+(base.height||0)])}}return points.length?points:[[0,0,0],[4000,3000,3000]]}
function fit(){let pts=allProjectionCoords(),{w,h}=rectangles();let projected=pts.map(([x,y,z])=>{if(App.view==='iso'){return [x*Math.cos(App.camera.yaw)-y*Math.sin(App.camera.y),(x*Math.sin(App.camera.y)+y*Math.cos(App.camera.y))*Math.sin(App.camera.pitch)-z*Math.cos(App.camera.pitch)]}if(App.view==='plan')return[x,-y];if(App.view==='front')return[x,-z];if(App.view==='rear')return[-x,-z];return[App.view==='right'?y:-y,-z]});const xs=projected.map(p=>p[0]),ys=projected.map(p=>p[1]),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys);App.camera.scale=Math.min((w-100)/Math.max(1200,maxx-minx),(h-100)/Math.max(1200,maxy-miny),.32);App.camera.ox=-(maxx+minx)/2*App.camera.scale;App.camera.oy=-(maxy+miny)/2*App.camera.scale;render()}
function hitTest(p){let best=null,dist=Infinity;for(const e of App.doc.elements){let target=e;if(['door','window'].includes(e.type)){let host=element(e.hostId);if(!host)continue;let midpoint=pointAt(host,e.u),d=Math.hypot(p.x-midpoint.x,p.y-midpoint.y);if(d<Math.max(200,e.width/2)&&d<dist){best=e;dist=d}continue}if(target.x1==null)continue;if(['slab','column'].includes(e.type)){let b=boxFor(e);if(p.x>=b.x1-100&&p.x<=b.x2+100&&p.y>=b.y1-100&&p.y<=b.y2+100){best=e;dist=0}continue}let dx=e.x2-e.x1,dy=e.y2-e.y1,L2=dx*dx+dy*dy||1,u=Math.max(0,Math.min(1,((p.x-e.x1)*dx+(p.y-e.y1)*dy)/L2));let d=Math.hypot(p.x-e.x1-u*dx,p.y-e.y1-u*dy);if(d<Math.max(180,e.thickness/2+100)&&d<dist){best=e;dist=d}}return best}
function worldGizmo(){
 const e=element(App.selected);if(!e||!['iso','plan'].includes(App.view)||e.x1===undefined)return null;
 const x=(e.x1+e.x2)/2,y=(e.y1+e.y2)/2,z=Number(e.z||0)+(Number(e.height||0))/2;
 const o=projection(x,y,z),axes={x:projection(x+650,y,z),y:projection(x,y+650,z),z:projection(x,y,z+650)};return {o,axes};
}
function pickGizmoAxis(px,py){const g=worldGizmo();if(!g)return null;let result=null,best=14;for(const [axis,end] of Object.entries(g.axes)){const dx=end.x-g.o.x,dy=end.y-g.o.y,L2=dx*dx+dy*dy;if(L2<1)continue;const t=Math.max(0,Math.min(1,((px-g.o.x)*dx+(py-g.o.y)*dy)/L2));const d=Math.hypot(px-g.o.x-dx*t,py-g.o.y-dy*t);if(t>.15&&d<best){best=d;result={axis,dx,dy,L2}}}return result}
function drawWorldGizmo(){if(modifyMode!=='move'||!App.selected||App.view!=='iso')return;const g=worldGizmo();if(!g)return;ctx.save();ctx.lineWidth=3;ctx.font='bold 12px Arial';for(const [axis,end] of Object.entries(g.axes)){ctx.strokeStyle=axis==='x'?'#ce6047':axis==='y'?'#259271':'#3a72b5';ctx.fillStyle=ctx.strokeStyle;ctx.beginPath();ctx.moveTo(g.o.x,g.o.y);ctx.lineTo(end.x,end.y);ctx.stroke();ctx.fillText(axis.toUpperCase(),end.x+3,end.y+3)}ctx.restore()}
function onDown(ev){if(ev.button!==0&&ev.button!==1)return;canvas.setPointerCapture(ev.pointerId);const r=canvas.getBoundingClientRect(),px=ev.clientX-r.left,py=ev.clientY-r.top;const p=inversePlan(px,py);if(modifyMode==='move'&&App.view==='iso'&&ev.button===0){const hit=pickGizmoAxis(px,py);if(hit){App.drag={px,py,moved:false,edit3:{...hit,id:modifyFirst,origin:px,oy:py}};return}}if(modifyMode&&modifyMode!=='vertex'&&modifyMode!=='move'&&ev.button===0){modifyClick(ev,p);return}App.drag={px,py,p,moved:false,button:ev.button,ox:App.camera.ox,oy:App.camera.oy};if(ev.button===1||App.tool==='pan'||App.view!=='plan'){App.drag.pan=true;App.drag.orbit=App.view==='iso'&&ev.button===0&&App.tool!=='pan';App.drag.yaw=App.camera.yaw;App.drag.pitch=App.camera.pitch;return}if(['vertex','move'].includes(modifyMode)&&ev.button===0){const e=element(modifyFirst);if(!e)return;const which=nearestEndpoint(e,p);const h=projection(e['x'+which],e['y'+which]);const center=projection((e.x1+e.x2)/2,(e.y1+e.y2)/2);const target=modifyMode==='vertex'?h:center;if(Math.hypot(px-target.x,py-target.y)>16){modMessage('Grab the visible handle within 16 screen pixels');App.drag=null;return}App.drag.edit={mode:modifyMode,which,id:e.id,origin:{...p},before:clone(e)};return}if(App.tool==='select'){let e=hitTest(p);App.selected=e?.id||null;App.drag.id=e?.id||null;render();return}if(['door','window'].includes(App.tool)){insertOpening(p);return}let snapped=snapPoint(p,App.draft,ev.shiftKey);if(App.tool==='wall'){addWallPolylineVertex(snapped)}else if(App.tool==='column'){createElement(snapped,snapped);App.draft=null}else if(!App.draft){App.draft=snapped;App.mouse=snapped}else{createElement(App.draft,snapped);App.draft=null}render()}
function onMove(ev){let r=canvas.getBoundingClientRect(),px=ev.clientX-r.left,py=ev.clientY-r.top,p=inversePlan(px,py);$('coords').textContent=`X ${Math.round(p.x)} · Y ${Math.round(p.y)} mm`;if(App.drag){let d=App.drag;if(Math.hypot(px-d.px,py-d.py)>4)d.moved=true;if(d.edit3){const hit=d.edit3,t=((px-d.px)*hit.dx+(py-d.py)*hit.dy)/hit.L2;App.gizmo3Preview={axis:hit.axis,delta:t*650};render();return}if(d.edit){App.mouse=snapPoint(p);App.gizmoPreview={...App.mouse,mode:d.edit.mode,which:d.edit.which,id:d.edit.id};render();return}if(d.pan){if(d.orbit){App.camera.yaw=d.yaw+(px-d.px)*.008;App.camera.pitch=Math.max(.12,Math.min(1.4,d.pitch+(py-d.py)*.006))}else{App.camera.ox=d.ox+px-d.px;App.camera.oy=d.oy+py-d.py}render();return}if(App.tool==='select'&&d.id&&d.moved&&App.view==='plan'){const ddx=(px-d.px)/App.camera.scale,ddy=-(py-d.py)/App.camera.scale;App.mouse=snapPoint({x:d.p.x+ddx,y:d.p.y+ddy});render();return}}if(App.draft){App.mouse=snapPoint(p,App.draft,ev.shiftKey);render()}}
function onUp(ev){let d=App.drag;if(!d)return;const r=canvas.getBoundingClientRect(),p=inversePlan(ev.clientX-r.left,ev.clientY-r.top);if(d.edit3){const hit=d.edit3,t=((ev.clientX-r.left-d.px)*hit.dx+(ev.clientY-r.top-d.py)*hit.dy)/hit.L2;let delta=t*650,step=+($('gridStep').value||250);if($('gridSnap').checked)delta=Math.round(delta/step)*step;try{if(delta)commit(()=>{const e=element(hit.id);if(!e)throw Error('Element missing');if(hit.axis==='z'){e.z=Number(e.z||0)+delta;for(const o of App.doc.elements.filter(o=>o.hostId===e.id))o.z+=delta}else{const key=hit.axis+'1',key2=hit.axis+'2';e[key]+=delta;e[key2]+=delta}},'3D GIZMO '+hit.axis.toUpperCase()+' '+Math.round(delta)+' mm')}catch(err){modMessage(err.message)}App.gizmo3Preview=null;App.drag=null;modifyMode=null;render();return}if(d.edit){const ed=d.edit,q=snapPoint(p);try{commit(()=>{const e=element(ed.id);if(ed.mode==='vertex'&&e.pathId)moveSharedVertex(App.doc.elements,e.id,ed.which,q);else if(ed.mode==='vertex')setEndpoint(e,ed.which,q);else {const dx=q.x-ed.origin.x,dy=q.y-ed.origin.y;for(const k of ['x1','x2'])e[k]+=dx;for(const k of ['y1','y2'])e[k]+=dy}},'GIZMO EDIT APPLIED')}catch(err){modMessage(err.message)}modifyMode=null;App.gizmoPreview=null;App.drag=null;render();return}if(App.tool==='select'&&d.id&&d.moved&&App.view==='plan'){let delta=snapPoint(p),origin=snapPoint(d.p),dx=delta.x-origin.x,dy=delta.y-origin.y;if(dx||dy)commit(()=>{let e=element(d.id);if(e&&e.x1!=null){e.x1+=dx;e.x2+=dx;e.y1+=dy;e.y2+=dy}},'ELEMENT MOVED')}else if(App.draft&&d.moved&&App.view==='plan'){let b=snapPoint(p,App.draft,ev.shiftKey);if(App.tool==='wall')addWallPolylineVertex(b);else{createElement(App.draft,b);App.draft=null}}App.drag=null;render()}
function updateSidebar(){const e=element(App.selected),p=$('properties');if(!e){p.dataset.id='';if(!p.querySelector('.muted'))p.innerHTML='<p class="muted">Select a BIM element to edit geometry and metadata.</p>'}else if(p.dataset.id!==e.id){p.dataset.id=e.id;p.innerHTML=`<div class="muted">${e.id} · ${e.type} · ${e.discipline}</div><label>Name<input data-prop="name" value="${escapeHtml(e.name||'')}"></label><label>Assembly Tag<input data-prop="tag" placeholder="Auto-assigned when blank" value="${escapeHtml(e.tag||'')}"></label><label>Material<select data-prop="material">${['Concrete','Timber','Steel','Brick','Glass','Generic','Opening'].map(x=>`<option ${e.material===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Level<select data-prop="level">${Object.keys(levels).map(x=>`<option ${e.level===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="propertyGrid">${['x1','y1','x2','y2','z','height','thickness','width'].filter(k=>e[k]!==undefined).map(k=>`<label>${k.toUpperCase()} (mm)<input data-prop="${k}" type="number" value="${e[k]}"></label>`).join('')}</div><label>Classification<input data-prop="classification" value="${escapeHtml(e.classification||'')}"></label><button id="applyProperties">Apply Properties</button>`;p.querySelector('#applyProperties').onclick=()=>applyProperties();if(['door','window'].includes(e.type)){const profile=e.assemblyProfile||{};const box=document.createElement('div');box.className='assemblyProfile';box.innerHTML=`<h3>ASSEMBLY / FABRICATION DATA</h3><p class="muted">User-specified product details; manufacturer verification required for LOD 400.</p>${[['manufacturer','Manufacturer'],['product','Product / series'],['model','Model / SKU'],['revision','Catalog revision'],['sourceUrl','Specification URL'],['frameDepth','Frame depth (mm)'],['frameFace','Frame face (mm)'],['glazingCount','Glazing panes'],['glazingThickness','Glazing thickness (mm)'],['jambClearance','Jamb clearance (mm)'],['leafThickness','Door leaf thickness (mm)'],['fireRating','Fire rating'],['hardware','Hardware set'],['fasteners','Fasteners / anchors'],['installationNotes','Installation notes']].map(([key,label])=>`<label>${label}<input data-assembly="${key}" value="${escapeHtml(profile[key]??'')}"></label>`).join('')}<label>Documentation state<select id="assemblyVerification"><option value="unverified">Unverified</option><option value="user-verified">User reviewed</option><option value="manufacturer-document">Manufacturer document checked</option></select></label><button id="saveAssembly">Save assembly details</button><button id="checkAssembly">Check LOD 400 fields</button><p id="assemblyFeedback" class="muted"></p>`;p.append(box);box.querySelector('#assemblyVerification').value=profile.verification||'unverified';box.querySelector('#saveAssembly').onclick=()=>{try{const updated={...profile};box.querySelectorAll('[data-assembly]').forEach(input=>updated[input.dataset.assembly]=input.value);updated.verification=box.querySelector('#assemblyVerification').value;const norm=normalizeProfile(updated);commit(()=>{e.assemblyProfile=norm},'ASSEMBLY SPECIFICATIONS UPDATED');p.dataset.id='';render();status('ASSEMBLY DATA SAVED')}catch(error){box.querySelector('#assemblyFeedback').textContent=error.message}};box.querySelector('#checkAssembly').onclick=()=>{box.querySelector('#assemblyFeedback').textContent=validateProductAssembly({...e,assemblyProfile:normalizeProfile({...profile,...Object.fromEntries([...box.querySelectorAll('[data-assembly]')].map(x=>[x.dataset.assembly,x.value])),verification:box.querySelector('#assemblyVerification').value})}).join(' · ')||'Required documentation fields present; technical validation remains a reviewer responsibility.'}}}else{ /* avoid disrupting live property edits */ }const browser=$('browser'),sig=App.doc.elements.map(x=>x.id+':'+x.name).join('|')+'|'+App.selected;if(browser.dataset.signature!==sig){browser.dataset.signature=sig;browser.innerHTML=App.doc.elements.map(x=>`<button data-element-id="${x.id}" class="${x.id===App.selected?'active':''}">${x.name} · ${x.type} · ${x.level}</button>`).join('');browser.querySelectorAll('[data-element-id]').forEach(b=>b.onclick=()=>{App.selected=b.dataset.elementId;$('properties').dataset.id='';render()})}$('count').textContent=`${App.doc.elements.length} objects`;$('projectName').textContent=App.doc.title;}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function applyProperties(){const e=element(App.selected);if(!e)return;let changes={};$('properties').querySelectorAll('[data-prop]').forEach(inp=>{const k=inp.dataset.prop;changes[k]=inp.type==='number'?+inp.value:inp.value});if(Object.entries(changes).some(([k,v])=>typeof v==='number'&&!Number.isFinite(v)))return status('INVALID PROPERTY · Non-finite coordinate');commit(()=>{if(e.pathId&&e.type==='wall')for(const end of [1,2])if(('x'+end in changes)||('y'+end in changes))moveSharedVertex(App.doc.elements,e.id,end,{x:changes['x'+end]??e['x'+end],y:changes['y'+end]??e['y'+end]});Object.assign(e,changes);if(e.level in levels&& !('z' in changes))e.z=levels[e.level];for(const o of App.doc.elements.filter(x=>x.hostId===e.id))o.thickness=e.thickness},'ELEMENT PROPERTIES UPDATED');$('properties').dataset.id='';render()}
function quantities(){const rows=App.doc.elements.filter(e=>!['line','dimension'].includes(e.type)).map(e=>{const L=Math.hypot((e.x2||0)-(e.x1||0),(e.y2||0)-(e.y1||0));let net=e.type==='wall'?L*(e.height||0)*(e.thickness||0):['slab','column'].includes(e.type)?(e.type==='slab'?slabNetArea(e):Math.abs((e.x2-e.x1)*(e.y2-e.y1)))*(e.height||0):e.type==='beam'?L*e.thickness*(e.height||0):0;if(e.type==='wall'){for(const o of App.doc.elements.filter(x=>x.hostId===e.id))net-=o.width*o.height*e.thickness}return {id:e.id,name:e.name,type:e.type,level:e.level,length:L,volume:Math.max(0,net)/1e9}});return rows}
function audit(){let faults=[...validateAssembly(App.doc),...coordinateAudit(App.doc)];const ids=new Set;for(const e of App.doc.elements){if(ids.has(e.id))faults.push('Duplicate ID '+e.id);ids.add(e.id);for(const k of ['z','height','thickness'])if(!Number.isFinite(+e[k]))faults.push(e.id+' invalid '+k);if(['door','window'].includes(e.type)&&(!element(e.hostId)||element(e.hostId)?.type!=='wall'))faults.push(e.id+' missing wall host');if(e.type==='wall'&&Math.hypot(e.x2-e.x1,e.y2-e.y1)<20)faults.push(e.id+' wall too short')}return faults}
function showOverlay(title,content){$('overlayTitle').textContent=title;$('overlayContent').innerHTML=content;$('overlay').hidden=false}
function svgForView(view,rect={w:480,h:320}){const old={...App.camera},oldview=App.view;App.view=view;App.camera={...old,scale:.06,ox:0,oy:0};let pts=allProjectionCoords(),raw=pts.map(([x,y,z])=>{let Y=App.camera.yaw,P=App.camera.pitch;if(view==='iso')return [x*Math.cos(Y)-y*Math.sin(Y),(x*Math.sin(Y)+y*Math.cos(Y))*Math.sin(P)-z*Math.cos(P)];if(view==='plan')return[x,-y];if(view==='front')return[x,-z];if(view==='right')return[y,-z];return[-x,-z]});let minx=Math.min(...raw.map(p=>p[0])),maxx=Math.max(...raw.map(p=>p[0])),miny=Math.min(...raw.map(p=>p[1])),maxy=Math.max(...raw.map(p=>p[1])),s=Math.min((rect.w-45)/Math.max(1000,maxx-minx),(rect.h-45)/Math.max(1000,maxy-miny));function to(x,y,z){let u,v,Y=old.yaw,P=old.pitch;if(view==='iso'){u=x*Math.cos(Y)-y*Math.sin(Y);v=(x*Math.sin(Y)+y*Math.cos(Y))*Math.sin(P)-z*Math.cos(P)}else if(view==='plan'){u=x;v=-y}else if(view==='front'){u=x;v=-z}else if(view==='right'){u=y;v=-z}else{u=-x;v=-z}return [((u-(minx+maxx)/2)*s+rect.w/2).toFixed(1),((v-(miny+maxy)/2)*s+rect.h/2).toFixed(1)]}let paths='';const poly=(ar,fill)=>`<polygon points="${ar.map(p=>p.join(',')).join(' ')}" fill="${fill}" stroke="#537d87" stroke-width="1"/>`;for(const e of App.doc.elements){if(e.x1==null||['door','window'].includes(e.type))continue;if(e.type==='wall'||e.type==='beam'){let blocks=e.type==='wall'?openingSegments(e):[{a:{x:e.x1,y:e.y1},b:{x:e.x2,y:e.y2},z0:e.z,z1:e.z+e.height,thickness:e.thickness}];for(const b of blocks){let dx=b.b.x-b.a.x,dy=b.b.y-b.a.y,L=Math.hypot(dx,dy)||1,nx=-dy/L*b.thickness/2,ny=dx/L*b.thickness/2;let ps=[[b.a.x+nx,b.a.y+ny],[b.b.x+nx,b.b.y+ny],[b.b.x-nx,b.b.y-ny],[b.a.x-nx,b.a.y-ny]];if(view==='plan')paths+=poly(ps.map(p=>to(...p,0)),'#d2e3e6');else{paths+=poly([to(...ps[0],b.z0),to(...ps[1],b.z0),to(...ps[1],b.z1),to(...ps[0],b.z1)],'#c4dadd');paths+=poly(ps.map(p=>to(...p,b.z1)),'#e5eff1')}}}else if(['slab','column'].includes(e.type)){let b=boxFor(e),corners=[[b.x1,b.y1],[b.x2,b.y1],[b.x2,b.y2],[b.x1,b.y2]];paths+=poly(corners.map(p=>to(...p,e.z+(view==='plan'?0:e.height))),'#d5e6e7')}else{let a=to(e.x1,e.y1,e.z),b=to(e.x2,e.y2,e.z);paths+=`<path d="M${a.join(' ')} L${b.join(' ')}" stroke="#297987" stroke-width="1.5"/>`}}App.camera=old;App.view=oldview;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${rect.w} ${rect.h}" width="${rect.w}" height="${rect.h}"><rect width="100%" height="100%" fill="white"/><g>${paths}</g><text x="12" y="18" font-family="Arial" font-size="12" fill="#214e55">${view.toUpperCase()}</text></svg>`}
function saveFile(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
const escSvg=s=>s.replaceAll('<svg','<svg');
function actions(a){if(a==='bim-setup'){ensureCoordination(App.doc);showOverlay('COORDINATION · GRIDS & LEVELS',`<p>Edit levels and orthogonal structural grids in millimetres. Updating a datum moves its assigned assemblies.</p><div id="bimSetupFields"></div><button id="bimApply">Apply Project Datums</button>`);const mount=$('bimSetupFields');const makeField=(label,value,attr)=>{const wrap=document.createElement('label');wrap.style.display='block';wrap.style.margin='9px 0';wrap.textContent=label+' ';const inp=document.createElement('input');inp.value=value;inp.setAttribute('data-bim',attr);inp.style.width='95%';wrap.append(inp);mount.append(wrap)};for(const l of App.doc.levels)makeField(`${l.id} · ${l.name} elevation`,String(l.z),'level:'+l.id);makeField('X grids · comma separated',App.doc.grids.x.join(', '),'x');makeField('Y grids · comma separated',App.doc.grids.y.join(', '),'y');$('bimApply').onclick=()=>{try{const edits=[...mount.querySelectorAll('[data-bim]')];const grids={};const updated=[];for(const inp of edits){const id=inp.dataset.bim;if(id.startsWith('level:')){const z=Number(inp.value);if(!Number.isFinite(z))throw Error('Invalid datum '+id);updated.push([id.slice(6),z])}else{const values=inp.value.split(',').map(v=>Number(v.trim()));if(!values.length||values.some(v=>!Number.isFinite(v))||new Set(values).size!==values.length)throw Error('Invalid grid positions');grids[id]=values.sort((a,b)=>a-b)}}commit(()=>{for(const [id,z] of updated)setLevelElevation(App.doc,id,z);App.doc.grids=grids;syncLevels()},'PROJECT GRIDS / LEVELS UPDATED');actions('close-overlay')}catch(err){status('DATUM ERROR · '+err.message)}};return}if(a==='code-review'){ensureCoordination(App.doc);const c=App.doc.codeBasis;showOverlay('PROJECT CODE BASIS · IBC / OBC / ISO',`<p>Record jurisdiction, edition and classification. This is a code-data completeness review only; no code compliance is certified.</p><div id="codeFields"></div><button id="codeSave">Save Code Basis</button><div id="codeChecklist"></div>`);const host=$('codeFields');for(const [k,label] of Object.entries({jurisdiction:'Jurisdiction (IBC / OBC / other)',edition:'Code edition / amendments',occupancy:'Occupancy',constructionType:'Construction type',fireRatingBasis:'Fire rating basis',responsibleReviewer:'Reviewer'})){const lab=document.createElement('label');lab.style.display='block';lab.textContent=label+' ';const input=document.createElement('input');input.value=c[k]||'';input.dataset.codeField=k;lab.append(input);host.append(lab)}const refresh=()=>{$('codeChecklist').innerHTML='<h3>Review checklist</h3>'+codeChecklist(App.doc).map(x=>`<p>${x.item}: <b>${x.state}</b></p>`).join('')};$('codeSave').onclick=()=>{commit(()=>{for(const input of host.querySelectorAll('[data-code-field]'))App.doc.codeBasis[input.dataset.codeField]=input.value},'CODE BASIS UPDATED');refresh()};refresh();return}if(a==='verify-solids'){try{const check=verifyKernel();let solids=App.doc.elements.filter(e=>['wall','beam','slab','column'].includes(e.type)).map(e=>solidForElement(e,App.doc));showOverlay('SOLID ENGINE — VERIFIED SCOPE',`<p><b>Rectilinear CSG self-test passed.</b> ${check.tests} exact-volume tests. ${solids.length} assembly solids built.</p><p>Calculated net volume: ${(solids.reduce((n,s)=>n+s.volumeM3,0)).toFixed(5)} m³</p><p><b>Scope:</b> Dimensionally exact partitioned prismatic solids and rectangular hosted cuts. NOT OpenCascade, NOT general-purpose B-rep, no arbitrary curved solids, no cross-assembly union, and surface triangulation may have T-junctions.</p>`);const walls=App.doc.elements.filter(e=>e.type==='wall'&&e.visible!==false);let joinInfo='';try{if(walls.length)joinInfo=' Orthogonal union: '+unionOrthogonalWalls(walls).volumeM3.toFixed(5)+' m³.'}catch(err){joinInfo=' Union limited: '+err.message}status('RECTILINEAR SOLID KERNEL VERIFIED.'+joinInfo)}catch(error){result('SOLID ENGINE TEST FAILED: '+error.message);status('SOLID ENGINE FAILED')}}else if(a==='author'){const report=validateAssemblies(App.doc);showOverlay('SUBSTRATE PRO · AUTO AUTHOR / DOCUMENT SET',`<p><b>${report.rows.length} BIM assemblies coordinated.</b> Live tags, associative lengths, host openings and material takeoffs are generated from model fields.</p><div class="toolset"><button id="authorPlot">Open Scaled Sheet Composer</button><button id="authorCSV">Export Schedule CSV</button></div>${scheduleHTML(App.doc)}<p>Auto annotations appear on the next scaled plot. This is conceptual AEC documentation, not certified construction documentation.</p>`);$('authorPlot').onclick=()=>actions('plot');$('authorCSV').onclick=()=>actions('schedule-csv');return}if(a==='schedule-csv'){saveFile('SUBSTRATE_PRO_schedule.csv',scheduleCSV(App.doc),'text/csv;charset=utf-8');status('ASSOCIATIVE SCHEDULE EXPORTED');return}if(a==='plot'||a==='print'){App.doc.autoAnnotations=$('autoAnnotations').checked;showOverlay('SUBSTRATE PRO · PROFESSIONAL PLOT / SHEET COMPOSER','<div id="plotMount"></div>');mountPlotUI($('plotMount'),App.doc,{save:saveFile});return}if(a==='new'){if(App.doc.elements.length&&!confirm('Create new project? Unsaved changes will be lost.'))return;history();App.doc={title:'Untitled AEC Model',elements:[]};syncLevels();App.selected=null;$('properties').dataset.id='';render();status('NEW PROJECT CREATED')}else if(a==='open')$('filePicker').click();else if(a==='save'){saveFile((App.doc.title||'substrate').replace(/[^\w-]+/g,'_')+'.substratepro',JSON.stringify({format:'SUBSTRATE_PRO',version:1,document:App.doc},null,2),'application/json');status('PROJECT SAVED')}else if(a==='undo'){finishWallPath();if(App.history.length){App.future.push(clone(App.doc));App.doc=App.history.pop();App.selected=null;$('properties').dataset.id='';render();status('UNDO')}}else if(a==='redo'){finishWallPath();if(App.future.length){App.history.push(clone(App.doc));App.doc=App.future.pop();App.selected=null;$('properties').dataset.id='';render();status('REDO')}}else if(a==='delete'){if(!App.selected)return status('SELECT AN OBJECT TO DELETE');let id=App.selected;commit(()=>{App.doc.elements=App.doc.elements.filter(e=>e.id!==id&&e.hostId!==id);App.selected=null},'OBJECT DELETED');$('properties').dataset.id=''}else if(a==='duplicate'){const e=element(App.selected);if(!e)return status('SELECT AN OBJECT FIRST');commit(()=>{let copy={...clone(e),id:uid(),name:e.name+' Copy'};if(copy.x1!=null){copy.x1+=500;copy.x2+=500;copy.y1+=500;copy.y2+=500}App.doc.elements.push(copy);App.selected=copy.id},'OBJECT DUPLICATED');$('properties').dataset.id=''}else if(a==='clearselect'){App.selected=null;$('properties').dataset.id='';render()}else if(a==='fit')fit();else if(a==='sample')loadSample();else if(a==='export-svg')saveFile('SUBSTRATE_PRO_plan.svg',svgForView('plan',{w:1100,h:760}),'image/svg+xml');else if(a==='export-png'){canvas.toBlob(blob=>{if(!blob)return;const u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='SUBSTRATE_PRO_view.png';link.click();setTimeout(()=>URL.revokeObjectURL(u),1200)},'image/png');status('PNG IMAGE EXPORTED')}else if(a==='sheet'||a==='section'||a==='presentation'){let views=a==='section'?['front','right']:a==='presentation'?['iso']:['plan','iso','front','right'];showOverlay(a==='presentation'?'PRESENTATION / MODEL':a==='section'?'SECTIONS / ELEVATIONS':'ORTHOGRAPHIC REVIEW SHEET',`<div style="display:grid;grid-template-columns:${views.length>1?'1fr 1fr':'1fr'};gap:12px">${views.map(v=>svgForView(v,{w:480,h:300})).join('')}</div><p>Model-derived preliminary projections. Not certified construction sheets.</p>`)}else if(a==='schedule'){let rows=quantities();showOverlay('CONCEPTUAL QUANTITY SCHEDULE',`<table><thead><tr><th>Element</th><th>Type</th><th>Level</th><th>Length (m)</th><th>Net Volume (m³)</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(r.name)}</td><td>${r.type}</td><td>${r.level}</td><td>${(r.length/1000).toFixed(2)}</td><td>${r.volume.toFixed(3)}</td></tr>`).join('')}</tbody></table><p>Calculated from conceptual geometry. Not certified for procurement or code compliance.</p>`)}else if(a==='audit'){let issues=audit();result(issues.length?issues.join('\n'):`Model audit passed: ${App.doc.elements.length} elements, valid IDs and hosted references.`);status(issues.length?`AUDIT · ${issues.length} ISSUE(S)`:'AUDIT PASSED')}else if(a==='guide')showOverlay('SUBSTRATE PRO · WORKFLOW GUIDE','<p><b>1. Draw:</b> Select Plan and Wall. Click start, then end. Alternatively drag. Endpoint and grid snapping are active. Shift permits angled walls.</p><p><b>2. Create assemblies:</b> Choose Door or Window and click near an existing wall. The opening is hosted and included in 3D projection and net wall quantities.</p><p><b>3. Edit:</b> Select an object, change properties on the right and click Apply. Use Undo/Redo and levels to manage the model.</p><p><b>4. Review:</b> Choose 3D Iso, Front, Right, or 4 Ortho Sheet. Scroll to zoom. Middle-drag to pan.</p><p><b>5. Publish:</b> Save native .substratepro JSON, export a plan SVG or print a review sheet.</p><p><b>Scope:</b> Browser-native conceptual geometry; not an OpenCascade B-rep implementation or certified IFC authoring system.</p>');else if(a==='close-overlay')$('overlay').hidden=true;else if(a==='print'){if($('overlay').hidden)actions('sheet');window.print()}}
function loadSample(){const sample=[{type:'slab',name:'Ground slab',x1:-3000,y1:-2000,x2:3000,y2:2000,z:-250,height:250,thickness:250},{type:'wall',name:'North wall',x1:-3000,y1:2000,x2:3000,y2:2000,z:0,height:3000,thickness:200},{type:'wall',name:'West wall',x1:-3000,y1:-2000,x2:-3000,y2:2000,z:0,height:3000,thickness:200},{type:'wall',name:'East wall',x1:3000,y1:-2000,x2:3000,y2:2000,z:0,height:3000,thickness:200},{type:'column',name:'Interior column',x1:0,y1:0,x2:400,y2:400,z:0,height:3000,thickness:400}].map(e=>({id:uid(),material:'Concrete',level:'L1',classification:'',visible:true,discipline:'Architecture',...e}));sample.push({id:uid(),name:'North window',type:'window',material:'Glass',level:'L1',hostId:sample[1].id,u:.5,width:1400,z:950,height:1250,thickness:200,visible:true,discipline:'Architecture'});commit(()=>{App.doc={title:'AEC Assembly Concept',elements:sample};App.selected=null},'SAMPLE PROJECT LOADED');$('properties').dataset.id='';$('projectName').textContent=App.doc.title;fit()}
let modifyMode=null,modifyFirst=null,modifyStart=null;
function modMessage(s){$('modifyPrompt').textContent=s;status(s)}
function modifySelect(id){const mode=id;let e=element(App.selected);if(!e){modMessage('Select an element first, then choose '+mode);return}if(mode==='flip'){commit(()=>{flipElement(e);for(const o of App.doc.elements.filter(o=>o.hostId===e.id))o.u=1-o.u},'DIRECTION FLIPPED');return}if(mode==='rotate'){if(!['wall','beam','line','dimension'].includes(e.type)){modMessage('Rotate supports linear elements; rectangular slab rotation is not yet available');return}let a=+$('modifyAngle').value||90;const p={x:(e.x1+e.x2)/2,y:(e.y1+e.y2)/2};commit(()=>{rotateElement(e,a,p)},'ROTATED '+a+'°');return}if(mode==='offset'){if(!['wall','beam','line','dimension'].includes(e.type)){modMessage('Offset supports linear elements');return}const d=+$('modifyDistance').value||250;commit(()=>offsetSegment(e,d),'OFFSET '+d+' mm');return}if(mode==='join'||mode==='fillet'||mode==='extend'||mode==='trim'){if(!['wall','beam','line'].includes(e.type)){modMessage('Choose a wall or linear element');return}modifyFirst=e.id;modifyMode=mode;modMessage('Click the SECOND wall/line in Plan to '+mode+'.');setView('plan');return}if(mode==='cut'){if(!['wall','beam','line'].includes(e.type)){modMessage('Split requires a wall, beam or line');return}modifyFirst=e.id;modifyMode='cut';modMessage('Click split point on selected wall/beam in Plan');setView('plan');return}if(mode==='vertex'||mode==='move'){modifyFirst=e.id;modifyMode=mode;modMessage(mode==='move'?'Drag X/Y/Z axis handles in 3D Iso, or center handle in Plan. Esc cancels':'Drag the vertex handle in Plan. Esc cancels');if(mode==='vertex')setView('plan');render();return}if(mode==='slabhole'){if(e.type!=='slab'){modMessage('Select a slab before cutting a floor void');return}modifyFirst=e.id;modifyMode=mode;modMessage('Click two opposite rectangle corners inside the slab');setView('plan');return}if(mode==='wallhole'){if(e.type!=='wall'){modMessage('Select a wall for elevation opening');return}const width=+(prompt('Opening width (mm)',900)||0),height=+(prompt('Opening height (mm)',2100)||0),sill=+(prompt('Sill above wall base (mm)',0)||0);try{const cut=wallHole(e,{u:.5,width,height,sill});commit(()=>App.doc.elements.push({id:uid(),type:'window',name:'Wall elevation cut',material:'Opening',level:e.level,z:e.z+sill,height,width,thickness:e.thickness,hostId:e.id,u:cut.u,discipline:'Architecture',visible:true}), 'HOSTED WALL OPENING CREATED')}catch(err){modMessage(err.message)}return}}
function modifyClick(ev,p){if(!modifyMode)return false;const first=element(modifyFirst);if(!first){modifyMode=null;return false}try{if(['join','fillet','extend','trim'].includes(modifyMode)){const target=hitTest(p);if(!target||target.id===first.id||!['wall','beam','line'].includes(target.type)){modMessage('Click a different wall/line');return true}let mode=modifyMode;const radius=+$('modifyDistance').value||250;commit(()=>{if(mode==='join')joinWalls(first,target,radius);else if(mode==='fillet'){const f=rightAngleFillet(first,target,radius);for(let i=1;i<f.points.length;i++)App.doc.elements.push({...first,id:uid(),name:'Fillet arc segment',arcGroup: first.id+'-'+target.id,arc: f.arc,arcSegment:i,arcSegments:f.points.length-1,x1:f.points[i-1].x,y1:f.points[i-1].y,x2:f.points[i].x,y2:f.points[i].y})}else trimExtend(first,target,p,mode)},'MODIFY · '+mode.toUpperCase());modifyMode=null;return true}if(modifyMode==='cut'){const L=length(first),dx=first.x2-first.x1,dy=first.y2-first.y1,t=((p.x-first.x1)*dx+(p.y-first.y1)*dy)/(L*L);if(t<=.03||t>=.97)throw Error('Split must be inside element');const q={x:first.x1+t*dx,y:first.y1+t*dy};commit(()=>{const second={...clone(first),id:uid(),x1:q.x,y1:q.y};first.x2=q.x;first.y2=q.y;App.doc.elements.push(second);for(const o of App.doc.elements.filter(o=>o.hostId===first.id)){if(o.u>t){o.hostId=second.id;o.u=(o.u-t)/(1-t)}else o.u/=t}},'LINEAR ELEMENT SPLIT');modifyMode=null;return true}if(modifyMode==='slabhole'){if(!modifyStart){modifyStart=snapPoint(p);modMessage('Click opposite corner of slab opening');return true}const a=modifyStart,b=snapPoint(p);commit(()=>holeForSlab(first,{x1:a.x,y1:a.y,x2:b.x,y2:b.y}),'SLAB OPENING ADDED');modifyMode=null;modifyStart=null;return true}}catch(err){modMessage('MODIFY REJECTED · '+err.message);modifyMode=null;modifyStart=null;return true}return false}
function drawModifyGizmo(){if(App.view==='plan'){for(const e of App.doc.elements.filter(x=>x.type==='slab'))for(const h of e.holes||[]){const a=projection(h.x1,h.y1),b=projection(h.x2,h.y2);ctx.fillStyle='#fff';ctx.fillRect(Math.min(a.x,b.x),Math.min(a.y,b.y),Math.abs(a.x-b.x),Math.abs(a.y-b.y));ctx.strokeStyle='#ae5960';ctx.lineWidth=1.4;ctx.strokeRect(Math.min(a.x,b.x),Math.min(a.y,b.y),Math.abs(a.x-b.x),Math.abs(a.y-b.y))}}if(App.view!=='plan'||!App.selected)return;const e=element(App.selected);if(!e||!Number.isFinite(e.x1))return;ctx.save();for(const [i,p] of [{x:e.x1,y:e.y1},{x:e.x2,y:e.y2}].entries()){const q=projection(p.x,p.y);ctx.fillStyle=i?'#0e7b80':'#e77c25';ctx.strokeStyle='white';ctx.lineWidth=2;ctx.fillRect(q.x-5,q.y-5,10,10);ctx.strokeRect(q.x-5,q.y-5,10,10)}const a=projection((e.x1+e.x2)/2,(e.y1+e.y2)/2);ctx.strokeStyle='#ce583c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(a.x+34,a.y);ctx.stroke();ctx.strokeStyle='#278469';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(a.x,a.y-34);ctx.stroke();ctx.font='bold 11px Arial';ctx.fillStyle='#a74331';ctx.fillText('X',a.x+36,a.y+4);ctx.fillStyle='#248066';ctx.fillText('Y',a.x-5,a.y-38);if(App.gizmoPreview){const q=projection(App.gizmoPreview.x,App.gizmoPreview.y);ctx.strokeStyle='#d35c1e';ctx.lineWidth=2;ctx.setLineDash([5,4]);ctx.beginPath();ctx.arc(q.x,q.y,9,0,Math.PI*2);ctx.stroke();ctx.setLineDash([])}ctx.restore()}
function wire(){const finishBtn=$('finishWall');if(finishBtn)finishBtn.addEventListener('click',()=>{finishWallPath();status('WALL POLYLINE FINISHED')});for(const b of $$('[data-mod]'))b.addEventListener('click',()=>{modifyMode=null;modifyStart=null;$$('[data-mod]').forEach(x=>x.classList.toggle('active',x===b));modifySelect(b.dataset.mod)});for(const b of $$('[data-tool]'))b.addEventListener('click',()=>{tool(b.dataset.tool);if(App.view!=='plan'&&b.dataset.tool!=='select'&&b.dataset.tool!=='pan')setView('plan')});for(const b of $$('[data-view]'))b.addEventListener('click',()=>setView(b.dataset.view));for(const b of $$('[data-action]'))b.addEventListener('click',()=>actions(b.dataset.action));for(const b of $$('[data-workflow]'))b.addEventListener('click',()=>{$$('[data-workflow]').forEach(x=>x.classList.toggle('active',x===b));const w=b.dataset.workflow;const actionsBy={project:'new',model:'fit',detail:'schedule',annotate:'guide',review:'sheet',publish:'save'};if(w==='model'){tool('wall');setView('plan')}else if(w==='detail')actions('schedule');else if(w==='annotate'){tool('dimension');setView('plan')}else if(w==='review')actions('sheet');else if(w==='publish')actions('sheet');else showOverlay('PROJECT / FILE WORKFLOW','<p>Use New, Open, Save, and Sample on the main toolbar. Save creates a native local project JSON file.</p>')});canvas.addEventListener('pointerdown',onDown);canvas.addEventListener('pointermove',onMove);canvas.addEventListener('pointerup',onUp);canvas.addEventListener('pointercancel',()=>{App.drag=null});canvas.addEventListener('wheel',ev=>{ev.preventDefault();App.camera.scale=Math.min(1.5,Math.max(.005,App.camera.scale*(ev.deltaY>0?.87:1.15)));render()},{passive:false});$('autoAnnotations').addEventListener('change',()=>{App.doc.autoAnnotations=$('autoAnnotations').checked;status('ANNOTATION PREFERENCE UPDATED')});$('showDatums').addEventListener('change',render);for(const id of ['gridStep','gridSnap','endpointSnap','ortho','gridVisible'])$(id).addEventListener('change',()=>{App.grid=$('gridVisible').checked;App.snap=$('gridSnap').checked;App.endpoints=$('endpointSnap').checked;App.ortho=$('ortho').checked;render()});$('filePicker').addEventListener('change',async ev=>{const f=ev.target.files[0];if(!f)return;try{const parsed=JSON.parse(await f.text()),doc=parsed.document||parsed;if(!Array.isArray(doc.elements))throw Error('Missing elements array');history();App.doc={...doc,title:String(doc.title||'Imported project'),elements:doc.elements};syncLevels();App.selected=null;$('properties').dataset.id='';$('projectName').textContent=App.doc.title;fit();status('PROJECT OPENED')}catch(err){status('OPEN FAILED · '+err.message)}ev.target.value=''});window.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&App.tool==='wall'&&App.wallPath){finishWallPath();status('WALL POLYLINE FINISHED');return}if(ev.key==='Escape'){finishWallPath();modifyMode=null;modifyStart=null;$$('[data-mod]').forEach(x=>x.classList.remove('active'));App.draft=null;App.drag=null;actions('close-overlay');render()}if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='z'){ev.preventDefault();actions(ev.shiftKey?'redo':'undo')}});syncLevels();new ResizeObserver(resize).observe($('stage'));resize();fit();App.initialized=true}
